import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int edges = n * (n - 1) / 2;
        int[][][] dpTable = new int[n + 1][edges + 1][n + 1];
        dpTable[1][0][1] = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= edges; j++) {
                for (int k = 1; k <= n; k++) {
                    int val = dpTable[i][j][k];
                    if (val == 0) continue;
                    if (j + i <= edges) {
                        dpTable[i + 1][j + i][i + 1] = (dpTable[i + 1][j + i][i + 1] + val) % m;
                    }
                    for (int l = 0; l < i; l++) {
                        int newJ = j + i - 1 - l;
                        if (newJ <= edges) {
                            dpTable[i + 1][newJ][k] = (dpTable[i + 1][newJ][k] + val) % m;
                        }
                    }
                }
            }
        }

        int[][][] prefixSumDP = new int[n + 1][n + 1][edges + 1];
        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= n; k++) {
                int total = 0;
                for (int j = 0; j <= edges; j++) {
                    total = (total + dpTable[i][j][k]) % m;
                    prefixSumDP[i][k][j] = total;
                }
            }
        }

        int[][][] cumulativeSum = new int[n + 1][edges + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= edges; j++) {
                int total = 0;
                for (int k = 0; k <= n; k++) {
                    total = (total + prefixSumDP[i][k][j]) % m;
                    cumulativeSum[i][j][k] = total;
                }
            }
        }

        int[] result = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            long res = (long) i * result[i - 1] % m;
            for (int k = 0; k <= n; k++) {
                for (int j = 1; j <= edges; j++) {
                    if (dpTable[i][j][k] == 0) continue;
                    int val = dpTable[i][j][k];
                    int sumVal = cumulativeSum[i][j - 1][n] - cumulativeSum[i][j - 1][k];
                    res = (res + (long) val * (sumVal % m)) % m;
                }
            }
            result[i] = (int) res;
        }

        System.out.println(result[n]);
        sc.close();
    }
}

